            fetchOrdersFromEndpoint(Constants.URL_GET_ORDERS_LEGACY + "?order_id=" + expectedOrderId, true);
        }
    }

    private void loadCachedActiveOrder() {
        SharedPreferences prefs = getSharedPreferences("fooddash_prefs", MODE_PRIVATE);
        String cachedOrder = prefs.getString("last_active_order_json", "");
        if (TextUtils.isEmpty(cachedOrder)) {
            if (expectedOrderId > 0) {
                showFallbackActiveOrder(expectedOrderId, Constants.STATUS_PENDING);
            }
            return;
        }

        try {
            JSONObject order = new JSONObject(cachedOrder);
            renderOrders(Collections.singletonList(order));
        } catch (Exception e) {
            Log.e(TAG, "Failed to load cached active order", e);
            if (expectedOrderId > 0) {
                showFallbackActiveOrder(expectedOrderId, Constants.STATUS_PENDING);
            }
        }
    }

    private void setupBottomNavigation() {
        highlightBottomTab(tabOrdersButton);

        if (tabHomeButton != null) {
            tabHomeButton.setOnClickListener(v -> {
                highlightBottomTab(tabHomeButton);
                Intent intent = new Intent(this, CustomerDashboard.class);
                intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP);
                startActivity(intent);
                finish();
            });
        }

        if (tabOrdersButton != null) {
            tabOrdersButton.setOnClickListener(v -> highlightBottomTab(tabOrdersButton));
        }

        if (tabCartButton != null) {
            tabCartButton.setOnClickListener(v -> {
                highlightBottomTab(tabCartButton);
                openCartFromPrefs();
            });
        }

        if (tabNotificationsButton != null) {
            tabNotificationsButton.setOnClickListener(v -> {
                highlightBottomTab(tabNotificationsButton);
                startActivity(new Intent(this, NotificationActivity.class));
                finish();
            });
        }

        if (tabProfileButton != null) {
            tabProfileButton.setOnClickListener(v -> {
                highlightBottomTab(tabProfileButton);
                startActivity(new Intent(this, ProfileActivity.class));
                finish();
            });
        }
    }

    private void highlightBottomTab(Button selected) {
        applyBottomTabStyle(tabHomeButton, selected == tabHomeButton);
        applyBottomTabStyle(tabOrdersButton, selected == tabOrdersButton);
        applyBottomTabStyle(tabCartButton, selected == tabCartButton);
        applyBottomTabStyle(tabNotificationsButton, selected == tabNotificationsButton);
        applyBottomTabStyle(tabProfileButton, selected == tabProfileButton);
    }

    private void applyBottomTabStyle(Button tab, boolean isSelected) {
        if (tab == null) return;
        if (isSelected) {
            tab.setBackgroundResource(R.drawable.bottom_nav_tab_selected);
            tab.setTextColor(getResources().getColor(R.color.white));
        } else {
            tab.setBackgroundResource(R.drawable.bottom_nav_tab_unselected);
            tab.setTextColor(getResources().getColor(R.color.black));
        }
    }

    private void updateCartBadgeFromPrefs() {
        if (tabCartBadgeTextView == null) return;
        int count = getCartItemCountFromPrefs();
        if (count <= 0) {
            tabCartBadgeTextView.setVisibility(View.GONE);
            return;
        }
        tabCartBadgeTextView.setVisibility(View.VISIBLE);
        tabCartBadgeTextView.setText(count > 99 ? "99+" : String.valueOf(count));
    }

    private int getCartItemCountFromPrefs() {
        SharedPreferences prefs = getSharedPreferences("fooddash_prefs", MODE_PRIVATE);
        int count = 0;
        try {
            JSONArray array = new JSONArray(prefs.getString("global_cart_json", "[]"));
            for (int i = 0; i < array.length(); i++) {
                JSONObject obj = array.optJSONObject(i);
                if (obj != null) count += obj.optInt("quantity", 0);
            }
        } catch (Exception ignored) {}
        return count;
    }

    private void openCartFromPrefs() {
        SharedPreferences prefs = getSharedPreferences("fooddash_prefs", MODE_PRIVATE);
        String cartJson = prefs.getString("global_cart_json", "[]");
        try {
            JSONArray cart = new JSONArray(cartJson);
            if (cart.length() == 0) {
                Toast.makeText(this, "Cart is empty", Toast.LENGTH_SHORT).show();
                return;
            }
        } catch (Exception ignored) {
            Toast.makeText(this, "Cart is empty", Toast.LENGTH_SHORT).show();
            return;
        }
        Intent intent = new Intent(this, CartActivity.class);
        intent.putExtra("cart_items_json", cartJson);
        startActivity(intent);
        finish();
    }

    private void fetchOrdersFromEndpoint(String url, boolean isLegacy) {
        JsonObjectRequest request = new JsonObjectRequest(
                Request.Method.GET,
                url,
                null,
                response -> {
                    List<JSONObject> orders = extractOrders(response);
                    if (!orders.isEmpty()) {
                        renderOrders(orders);
                    } else if (expectedOrderId > 0 && ordersContainer.getChildCount() == 0) {
                        showFallbackActiveOrder(expectedOrderId, Constants.STATUS_PENDING);
                    }
                },
                error -> {
                    if (isLegacy) Log.e(TAG, "Failed to poll legacy orders: " + error.toString());
                    if (expectedOrderId > 0 && ordersContainer.getChildCount() == 0) {
                        showFallbackActiveOrder(expectedOrderId, Constants.STATUS_PENDING);
                    }
                }
        ) {
            @Override
            public Map<String, String> getHeaders() {
                return buildAuthHeaders();
            }
        };
        requestQueue.add(request);
    }

    private List<JSONObject> extractOrders(JSONObject response) {
        List<JSONObject> list = new ArrayList<>();
        if (response == null) return list;

        JSONArray orders = response.optJSONArray("orders");
        if (orders == null) orders = response.optJSONArray("data");
        if (orders == null) {
            JSONObject data = response.optJSONObject("data");
            if (data != null) orders = data.optJSONArray("orders");
        }
        if (orders == null) {
            JSONObject data = response.optJSONObject("data");
            if (data != null) {
                JSONObject nestedOrder = data.optJSONObject("order");
                if (nestedOrder != null) {
                    list.add(nestedOrder);
                }
            }
        }

        if (orders == null) {
            JSONObject nestedOrder = response.optJSONObject("order");
            if (nestedOrder != null) {
                list.add(nestedOrder);
            }
        }

        if (orders != null) {
            for (int i = 0; i < orders.length(); i++) {
                JSONObject o = orders.optJSONObject(i);
                if (o != null) list.add(o);
            }
        } else {
            // Check if it's a single order object
            if (response.has("id") || response.has("order_id") || response.has("items") || response.has("status")) {
                list.add(response);
            } else if (response.has("data")) {
                JSONObject data = response.optJSONObject("data");
                if (data != null && (data.has("id") || data.has("order_id"))) {
                    list.add(data);
                }
            }
        }
        return list;
    }

    private void showFallbackActiveOrder(int orderId, String status) {
        JSONObject fallback = new JSONObject();
        try {
            fallback.put("id", orderId);
            fallback.put("order_id", orderId);
            fallback.put("status", status);
            fallback.put("restaurant_name", "Your Restaurant Order");
            fallback.put("total_amount", 0.0);
        } catch (Exception ignored) {
        }

        ordersContainer.removeAllViews();
        ordersContainer.addView(createOrderCard(fallback, orderId, ActiveOrderActivity.normalizeStatus(status)));
    }

    private void renderOrders(List<JSONObject> orders) {
        // Simple deduplication by ID
        Map<Integer, JSONObject> uniqueOrders = new HashMap<>();
        for (JSONObject o : orders) {
            int id = o.optInt("id", o.optInt("order_id", -1));
            if (id > 0) uniqueOrders.put(id, o);
        }

        if (uniqueOrders.isEmpty()) {
            if (expectedOrderId > 0) {
                showFallbackActiveOrder(expectedOrderId, getCachedActiveOrderStatus());
            } else if (ordersContainer.getChildCount() == 0) {
                showEmptyMessage("No active orders found.");
            }
            return;
        }

        List<JSONObject> sortedList = new ArrayList<>(uniqueOrders.values());
        // Sort by ID descending (newest first)
        Collections.sort(sortedList, (a, b) -> Integer.compare(b.optInt("id"), a.optInt("id")));

        List<JSONObject> visibleOrders = new ArrayList<>();

        for (JSONObject order : sortedList) {
            String status = ActiveOrderActivity.normalizeStatus(order.optString("status", ""));
            int orderId = order.optInt("id", order.optInt("order_id", -1));

            // Only show active orders unless it's specifically requested
            if (expectedOrderId != orderId) {
                if (Constants.STATUS_DELIVERED.equals(status) || Constants.STATUS_CANCELLED.equals(status)) {
                    continue;
                }
            }

            visibleOrders.add(order);
        }

        if (visibleOrders.isEmpty()) {
            if (expectedOrderId > 0) {
                showFallbackActiveOrder(expectedOrderId, getCachedActiveOrderStatus());
            } else if (ordersContainer.getChildCount() == 0) {
                showEmptyMessage("No active orders found.");
            }
            return;
        }

        ordersContainer.removeAllViews();
        for (JSONObject order : visibleOrders) {
            String status = ActiveOrderActivity.normalizeStatus(order.optString("status", ""));
            int orderId = order.optInt("id", order.optInt("order_id", -1));
            ordersContainer.addView(createOrderCard(order, orderId, status));
        }
    }

    private String getCachedActiveOrderStatus() {
        SharedPreferences prefs = getSharedPreferences("fooddash_prefs", MODE_PRIVATE);
        String cachedOrder = prefs.getString("last_active_order_json", "");
        if (TextUtils.isEmpty(cachedOrder)) {
            return Constants.STATUS_PENDING;
        }

        try {
            JSONObject order = new JSONObject(cachedOrder);
            return ActiveOrderActivity.normalizeStatus(order.optString("status", Constants.STATUS_PENDING));
        } catch (Exception e) {
            return Constants.STATUS_PENDING;
        }
    }

    private View createOrderCard(JSONObject order, int orderId, String status) {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setBackgroundResource(R.drawable.view_border);
        box.setPadding(32, 32, 32, 32);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        lp.setMargins(0, 0, 0, 32);
        box.setLayoutParams(lp);

        String restaurant = order.optString("restaurant_name", "Restaurant");
        double total = order.optDouble("total_amount", order.optDouble("total", 0.0));

        TextView header = new TextView(this);
        header.setText(String.format(Locale.getDefault(), "Order #%d - %s", orderId, restaurant));
        header.setTextSize(18f);
        header.setTypeface(null, android.graphics.Typeface.BOLD);
        header.setTextColor(getResources().getColor(android.R.color.black));
        box.addView(header);

        TextView statusText = new TextView(this);
        statusText.setPadding(0, 12, 0, 12);
        statusText.setText(renderTimeline(status));
        statusText.setLineSpacing(1.1f, 1.1f);
        box.addView(statusText);

        String location = firstNonEmpty(
                order.optString("driver_location", ""),
                order.optString("current_location", "")
        );
        // Render driver details if available
        JSONObject driverObj = order.optJSONObject("driver");
        String driverName = "";
        String driverPhone = "";
        String driverAvatar = "";
        if (driverObj != null) {
            driverName = firstNonEmpty(driverObj.optString("name"), driverObj.optString("driver_name"), driverObj.optString("full_name"));
            driverPhone = firstNonEmpty(driverObj.optString("phone"), driverObj.optString("contact"), driverObj.optString("mobile"));
            driverAvatar = firstNonEmpty(driverObj.optString("avatar"), driverObj.optString("image"), driverObj.optString("photo"));
        } else {
            driverName = firstNonEmpty(order.optString("driver_name"), order.optString("rider_name"));
            driverPhone = firstNonEmpty(order.optString("driver_phone"), order.optString("driver_contact"), order.optString("phone"));
            driverAvatar = firstNonEmpty(order.optString("driver_avatar"), order.optString("driver_image"));
        }

        if (!driverName.isEmpty() || !driverPhone.isEmpty() || !driverAvatar.isEmpty()) {
            LinearLayout driverBox = new LinearLayout(this);
            driverBox.setOrientation(LinearLayout.HORIZONTAL);
            driverBox.setPadding(0, 12, 0, 12);

            ImageView img = new ImageView(this);
            LinearLayout.LayoutParams imgLp = new LinearLayout.LayoutParams(120, 120);
            imgLp.setMargins(0, 0, 16, 0);
            img.setLayoutParams(imgLp);
            if (!driverAvatar.isEmpty()) {
                Glide.with(this).load(driverAvatar).placeholder(R.drawable.ic_launcher_foreground).into(img);
            } else {
                img.setImageResource(R.drawable.ic_launcher_foreground);
            }
            driverBox.addView(img);

            LinearLayout info = new LinearLayout(this);
            info.setOrientation(LinearLayout.VERTICAL);
            info.setLayoutParams(new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT));

            TextView dn = new TextView(this);
            dn.setText(!driverName.isEmpty() ? driverName : "Driver");
            dn.setTypeface(null, android.graphics.Typeface.BOLD);
            info.addView(dn);

            TextView dp = new TextView(this);
            dp.setText(!driverPhone.isEmpty() ? "Phone: " + driverPhone : "Phone: N/A");
            dp.setTextColor(getResources().getColor(R.color.primary_blue));
            if (!driverPhone.isEmpty()) {
                final String driverPhoneFinal = driverPhone;
                dp.setOnClickListener(v -> {
                    try {
                        Intent i = new Intent(Intent.ACTION_DIAL);
                        i.setData(Uri.parse("tel:" + driverPhoneFinal));
                        startActivity(i);
                    } catch (Exception ignored) {}
                });
            }
            info.addView(dp);

            driverBox.addView(info);
            box.addView(driverBox);
        }
        if (!location.isEmpty() && !"null".equalsIgnoreCase(location)) {
            TextView locText = new TextView(this);
            locText.setText("Driver location: " + location);
            locText.setTextSize(14f);
            locText.setPadding(0, 0, 0, 8);
            box.addView(locText);
        }

        TextView footer = new TextView(this);
        footer.setText(String.format(Locale.getDefault(), "Total: P%.2f", total));
        footer.setGravity(android.view.Gravity.END);
        footer.setTypeface(null, android.graphics.Typeface.BOLD);
        box.addView(footer);

        return box;
    }

    private void showEmptyMessage(String msg) {
        ordersContainer.removeAllViews();
        TextView empty = new TextView(this);
        empty.setText(msg);
        empty.setPadding(32, 64, 32, 32);
        empty.setGravity(android.view.Gravity.CENTER);
        ordersContainer.addView(empty);
    }

    private String renderTimeline(String status) {
        StringBuilder builder = new StringBuilder();
        int current = timeline.indexOf(status);

        if (current == -1) {
            for (int i = 0; i < timeline.size(); i++) {
                if (status.contains(timeline.get(i))) {
                    current = i;
                    break;
                }
            }
        }

        for (int i = 0; i < timeline.size(); i++) {
            String step = timeline.get(i);
            String prefix;
            if (current > i) prefix = "✓ ";
            else if (current == i) prefix = "▶ ";
            else prefix = "○ ";

            builder.append(prefix).append(getFriendlyStatus(step));
            if (i < timeline.size() - 1) builder.append("\n");
        }
        return builder.toString();
    }

    private String getFriendlyStatus(String status) {
        switch (status) {
            case Constants.STATUS_PENDING: return "Order Placed";
            case Constants.STATUS_ACCEPTED: return "Accepted by Restaurant";
            case Constants.STATUS_PREPARING: return "Preparing Food";
            case Constants.STATUS_READY: return "Food is Ready";
            case Constants.STATUS_PICKED_UP: return "Picked Up";
            case Constants.STATUS_ARRIVED_RESTAURANT: return "Driver at Store";
            case Constants.STATUS_OUT_FOR_DELIVERY: return "Out for Delivery";
            case Constants.STATUS_DELIVERED: return "Delivered";
            default: return status.replace("_", " ").toUpperCase();
        }
    }

    private String firstNonEmpty(String... values) {
        for (String v : values) {
            if (!TextUtils.isEmpty(v) && !"null".equalsIgnoreCase(v.trim())) return v.trim();
        }
        return "";
    }

    private Map<String, String> buildAuthHeaders() {
        Map<String, String> headers = new HashMap<>();
        String token = AuthSessionManager.getValidAccessTokenOrNull(this);
        if (!TextUtils.isEmpty(token)) headers.put("Authorization", "Bearer " + token);
        return headers;
    }
}

package com.example.fooddash;

public class Product {
    public int id;
    public String name;
    public String description;
    public double price;
    public String imageUrl;
    public boolean isAvailable;
    public int quantity = 0;
    public int restaurantId;
    public int restaurantID;
    public String restaurantName;

    public Product(int id, String name, String description, double price, String imageUrl, boolean available, int restaurantId, String restaurantName) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.price = price;
        this.imageUrl = imageUrl;
        this.isAvailable = available;
        this.restaurantId = restaurantId;
        this.restaurantID = restaurantId;
        this.restaurantName = restaurantName;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public String getDescription() { return description; }
    public double getPrice() { return price; }
    public String getImageUrl() { return imageUrl; }
    public boolean isAvailable() { return isAvailable; }
}

package com.example.fooddash;

import android.content.SharedPreferences;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.android.volley.Request;
import com.android.volley.RequestQueue;
import com.android.volley.toolbox.JsonArrayRequest;
import com.android.volley.toolbox.JsonObjectRequest;
import com.android.volley.toolbox.Volley;
import com.bumptech.glide.Glide;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public class RestaurantMenuActivity extends AppCompatActivity {

    private RecyclerView productsRecyclerView;
    private ProgressBar loadingProgressBar;
    private TextView titleTextView;
    private Button btnBackToDashboard;
    private RequestQueue requestQueue;
    private final List<Product> productList = new ArrayList<>();
    private final Map<String, CartEntry> globalCart = new LinkedHashMap<>();
    private ProductAdapter adapter;
    private int restaurantId = -1;
    private String restaurantName = "";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_restaurant_products);

        if (!AccessControlManager.requireAccess(this,
                AccessControlManager.Resource.CUSTOMER_DASHBOARD,
                AccessControlManager.Action.READ)) {
            return;
        }

        productsRecyclerView = findViewById(R.id.restaurantProductsRecyclerView);
        loadingProgressBar = findViewById(R.id.restaurantProductsLoading);
        titleTextView = findViewById(R.id.restaurantProductsTitle);
        btnBackToDashboard = findViewById(R.id.restaurantProductsBackButton);

        productsRecyclerView.setLayoutManager(new GridLayoutManager(this, 2));
        productsRecyclerView.setNestedScrollingEnabled(false);
        requestQueue = Volley.newRequestQueue(this);
        adapter = new ProductAdapter(productList);
        productsRecyclerView.setAdapter(adapter);

        restaurantId = getIntent().getIntExtra("restaurant_id", -1);
        restaurantName = getIntent().getStringExtra("restaurant_name");
        if (TextUtils.isEmpty(restaurantName)) restaurantName = "Restaurant Menu";
        titleTextView.setText(String.format(Locale.US, "%s - Menu", restaurantName));
        btnBackToDashboard.setOnClickListener(v -> finish());

        loadGlobalCart();
        fetchMenu();
    }

    private void fetchMenu() {
        if (restaurantId <= 0) {
            Toast.makeText(this, "Invalid restaurant", Toast.LENGTH_SHORT).show();
            finish();
            return;
        }

        loadingProgressBar.setVisibility(View.VISIBLE);
        String url = Constants.URL_GET_MENU_BY_RESTAURANT + "?restaurant_id=" + restaurantId;
        JsonObjectRequest req = new JsonObjectRequest(Request.Method.GET, url, null,
                response -> {
                    JSONArray menus = response.optJSONArray("menus");
                    if (menus == null) menus = response.optJSONArray("data");
                    if (menus == null) menus = new JSONArray();
                    bindMenuArray(menus);
                }, error -> {
                    JsonArrayRequest legacy = new JsonArrayRequest(Request.Method.GET,
                            Constants.URL_GET_MENU_LEGACY + "?restaurant_id=" + restaurantId,
                            null,
                            this::bindMenuArray,
                            legacyError -> {
                                loadingProgressBar.setVisibility(View.GONE);
                                Toast.makeText(this, "Failed to load menu", Toast.LENGTH_SHORT).show();
                            });
                    requestQueue.add(legacy);
                });
        requestQueue.add(req);
    }

    private void bindMenuArray(JSONArray menus) {
        productList.clear();
        for (int i = 0; i < menus.length(); i++) {
            JSONObject obj = menus.optJSONObject(i);
            if (obj == null) continue;
            Product p = parseProduct(obj);
            CartEntry ce = globalCart.get("res:" + restaurantId + ":id:" + p.id);
            if (ce != null) p.quantity = ce.quantity;
            productList.add(p);
        }
        loadingProgressBar.setVisibility(View.GONE);
        adapter.notifyDataSetChanged();
    }

    private Product parseProduct(JSONObject item) {
        int id = item.optInt("id", -1);
        String name = item.optString("name", "Item");
        String description = item.optString("description", "");
        double price = item.optDouble("price", 0.0);
        String imageUrl = normalizeImageUrl(item.optString("image_url", item.optString("image", "")));
        boolean available = isItemAvailable(item);
        return new Product(id, name, description, price, imageUrl, available, restaurantId, restaurantName);
    }

    private boolean isItemAvailable(JSONObject item) {
        if (item == null) return true;
        if (item.has("is_available")) {
            String val = item.optString("is_available", "1");
            return val.equals("1") || val.equalsIgnoreCase("true");
        }
        if (item.has("available")) {
            String val = item.optString("available", "1");
            return val.equals("1") || val.equalsIgnoreCase("true");
        }
        if (item.has("status")) {
            String val = item.optString("status", "").toLowerCase(Locale.ROOT);
            return val.equals("available") || val.equals("active") || val.equals("1");
        }
        if (item.has("stock")) {
            return item.optInt("stock", 1) > 0;
        }
        return true;
    }

    private String normalizeImageUrl(String url) {
        if (TextUtils.isEmpty(url)) return "";
        if (url.startsWith("http")) return url;
        return "http://" + Constants.IP_ADDRESS + "/" + url;
    }

    private void loadGlobalCart() {
        globalCart.clear();
        SharedPreferences prefs = getSharedPreferences("fooddash_prefs", MODE_PRIVATE);
        try {
            JSONArray array = new JSONArray(prefs.getString("global_cart_json", "[]"));
            for (int i = 0; i < array.length(); i++) {
                JSONObject obj = array.optJSONObject(i);
                if (obj == null) continue;
                CartEntry e = new CartEntry(
                        obj.optInt("restaurant_id"),
                        obj.optString("restaurant_name"),
                        obj.optInt("menu_item_id"),
                        obj.optString("name"),
                        obj.optDouble("price"),
                        obj.optInt("quantity")
                );
                globalCart.put("res:" + e.restaurantId + ":id:" + e.id, e);
            }
        } catch (Exception ignored) {
        }
    }

    private void saveGlobalCart() {
        JSONArray array = new JSONArray();
        for (CartEntry e : globalCart.values()) {
            JSONObject obj = new JSONObject();
            try {
                obj.put("restaurant_id", e.restaurantId);
                obj.put("restaurant_name", e.restaurantName);
                obj.put("menu_item_id", e.id);
                obj.put("name", e.name);
                obj.put("price", e.price);
                obj.put("quantity", e.quantity);
                array.put(obj);
            } catch (Exception ignored) {
            }
        }
        getSharedPreferences("fooddash_prefs", MODE_PRIVATE).edit().putString("global_cart_json", array.toString()).apply();
    }

    private void syncProductWithGlobalCart(Product product) {
        String key = "res:" + product.restaurantId + ":id:" + product.id;
        if (product.quantity <= 0) globalCart.remove(key);
        else globalCart.put(key, new CartEntry(product.restaurantId, product.restaurantName, product.id, product.name, product.price, product.quantity));
        saveGlobalCart();
    }

    private static class CartEntry {
        int restaurantId, id, quantity;
        String restaurantName, name;
        double price;

        CartEntry(int restaurantId, String restaurantName, int id, String name, double price, int quantity) {
            this.restaurantId = restaurantId;
            this.restaurantName = restaurantName;
            this.id = id;
            this.name = name;
            this.price = price;
            this.quantity = quantity;
        }
    }

    private class ProductAdapter extends RecyclerView.Adapter<ProductAdapter.ViewHolder> {
        private final List<Product> list;

        ProductAdapter(List<Product> list) {
            this.list = list;
        }

        @NonNull
        @Override
        public ViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
            return new ViewHolder(LayoutInflater.from(parent.getContext()).inflate(R.layout.product_item, parent, false));
        }

        @Override
        public void onBindViewHolder(@NonNull ViewHolder holder, int position) {
            Product pr = list.get(position);
            holder.name.setText(pr.name);
            holder.desc.setText(pr.description);
            holder.restaurant.setText(pr.restaurantName);
            holder.price.setText(String.format(Locale.US, "₱%.2f", pr.price));
            holder.qty.setText(String.valueOf(pr.quantity));
            Glide.with(holder.itemView).load(pr.imageUrl).into(holder.img);

            holder.restaurant.setVisibility(TextUtils.isEmpty(pr.restaurantName) ? View.GONE : View.VISIBLE);

            if (pr.isAvailable) {
                holder.itemView.setAlpha(1.0f);
                holder.unavailableText.setVisibility(View.GONE);
                holder.controlsLayout.setVisibility(View.VISIBLE);

                holder.plus.setOnClickListener(v -> {
                    pr.quantity++;
                    holder.qty.setText(String.valueOf(pr.quantity));
                    syncProductWithGlobalCart(pr);
                });
                holder.minus.setOnClickListener(v -> {
                    if (pr.quantity > 0) {
                        pr.quantity--;
                        holder.qty.setText(String.valueOf(pr.quantity));
                        syncProductWithGlobalCart(pr);
                    }
                });
            } else {
                holder.itemView.setAlpha(0.6f);
                holder.unavailableText.setVisibility(View.VISIBLE);
                holder.controlsLayout.setVisibility(View.GONE);
                holder.plus.setOnClickListener(null);
                holder.minus.setOnClickListener(null);
                if (pr.quantity > 0) {
                    pr.quantity = 0;
                    holder.qty.setText("0");
                    syncProductWithGlobalCart(pr);
                }
            }
        }

        @Override
        public int getItemCount() {
            return list.size();
        }

        class ViewHolder extends RecyclerView.ViewHolder {
            ImageView img;
            TextView name, desc, restaurant, price, qty, unavailableText;
            ImageButton plus, minus;
            View controlsLayout;

            ViewHolder(View v) {
                super(v);
                img = v.findViewById(R.id.productImageView);
                name = v.findViewById(R.id.productNameTextView);
                desc = v.findViewById(R.id.productDescriptionTextView);
                restaurant = v.findViewById(R.id.productRestaurantNameTextView);
                price = v.findViewById(R.id.productPriceTextView);
                qty = v.findViewById(R.id.quantityTextView);
                plus = v.findViewById(R.id.plusButton);
                minus = v.findViewById(R.id.minusButton);
                unavailableText = v.findViewById(R.id.unavailableTextView);
                controlsLayout = v.findViewById(R.id.quantityControlsLayout);
            }
        }
    }
}

